    updated_at timestamp without time zone DEFAULT now(),
    lead_stage character varying(50) DEFAULT 'Cold Lead'::character varying,
    account_id integer,
    converted_to_account_id integer,
    converted_to_contact_id integer,
    edp_macc_status character varying(50),
    affiliate_id integer,
    email_normalized text GENERATED ALWAYS AS (lower(TRIM(BOTH FROM email))) STORED,
    conversion_source character varying(30),
    phone_normalized text GENERATED ALWAYS AS (regexp_replace((COALESCE(phone, ''::character varying))::text, '[^0-9]'::text, ''::text, 'g'::text)) STORED,
    company_domain text GENERATED ALWAYS AS (
CASE
    WHEN ((email IS NOT NULL) AND (POSITION(('@'::text) IN (email)) > 0)) THEN lower(TRIM(BOTH FROM split_part((email)::text, '@'::text, 2)))
    ELSE NULL::text
END) STORED
);


